document.addEventListener("DOMContentLoaded", function () {
  const submenu = document.getElementById("our-people-submenu");
  if (!submenu) return;

  const offsetTop = submenu.offsetTop;
  let isSticky = false;

  window.addEventListener("scroll", function () {
    if (window.scrollY >= offsetTop && !isSticky) {
      isSticky = true;
      submenu.classList.add("sticky-animate"); // ativa a animação
      submenu.classList.add("sticky-submenu");
    } else if (window.scrollY < offsetTop && isSticky) {
      isSticky = false;
      submenu.classList.remove("sticky-submenu");
      submenu.classList.remove("sticky-animate");
    }
  });
});
